// Methods that store from a for-in or for-of head where sloppy mode and
// strict mode differ: into the read-only global `undefined` and into a
// property of a string (sloppy mode drops both stores; strict mode throws).
// A store into an undeclared name is refused for the whole package (SC1091),
// so it cannot appear here.
var shapes = {};
shapes.Bag = function (size) {
  this.size = size;
};
shapes.Bag.prototype.lastKey = function () {
  for (undefined in { first: 1, last: 2 });
  return typeof undefined + " " + this.size;
};
shapes.Cell = function (label) {
  this.label = label;
};
shapes.Cell.prototype.lastItem = function () {
  var label = this.label;
  for (label.item of [1, 2, 3]);
  return typeof label.item;
};
module.exports = { shapes: shapes };
